# TEST FIXTURE (id 93): an interior with no @area (area_id 0): leaving it to test_zone_a must NOT show the banner again (contract section 22).
@map test_zone_in
@size 8 6
@interior yes
@bg 3
@fill floor_lab
@spawn from_a 3 4 N
@legend
  .  tile=floor_lab
  C  tile=none object=wall_corner
  w  tile=none object=wall_j
  y  tile=none object=wall_win_j
  |  tile=none object=wall_i
  q  tile=none object=wall_win_i
  m  tile=mat
@grid
  Cwywwwyw
  |.......
  |.......
  |.......
  |.......
  |..mm...
@warp m -> test_zone_a spawn=from_in
